import bisect
class Solution:
    def maxTeamSize(self, startTime, endTime):
        S = sorted(startTime)
        E = sorted(endTime)
        best = 1
        for s, e in zip(startTime, endTime):
            cnt = bisect.bisect_right(S, e) - bisect.bisect_left(E, s)
            best = max(best, cnt)
        return best

