class Solution {
    public int maxTeamSize(int[] startTime, int[] endTime) {
        int n = startTime.length;
        int[] S = startTime.clone(), E = endTime.clone();
        java.util.Arrays.sort(S);
        java.util.Arrays.sort(E);
        int best = 1;
        for (int i = 0; i < n; i++) {
            int cnt = upper(S, endTime[i]) - lower(E, startTime[i]);
            best = Math.max(best, cnt);
        }
        return best;
    }
    private int upper(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] <= x) lo = m + 1; else hi = m; }
        return lo;
    }
    private int lower(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] < x) lo = m + 1; else hi = m; }
        return lo;
    }
}

