class Solution:
    def maxTeamSize(self, startTime, endTime):
        events = []
        for s, e in zip(startTime, endTime):
            events.append((e, 0))
            events.append((s, 1))
        events.sort()
        cur = best = 0
        for _, t in events:
            cur += 1 if t == 1 else -1
            best = max(best, cur)
        return max(best, 1)

