class Solution {
public:
    int maxTeamSize(vector<int>& startTime, vector<int>& endTime) {
        vector<pair<int,int>> ev;
        for (int i = 0; i < (int)startTime.size(); i++) {
            ev.push_back({endTime[i], 0});
            ev.push_back({startTime[i], 1});
        }
        sort(ev.begin(), ev.end());
        int cur = 0, best = 0;
        for (auto& [t, k] : ev) {
            cur += k == 1 ? 1 : -1;
            best = max(best, cur);
        }
        return max(best, 1);
    }
};

