class Solution {
    public int maxTeamSize(int[] startTime, int[] endTime) {
        int n = startTime.length;
        long[] ev = new long[2 * n];
        for (int i = 0; i < n; i++) {
            ev[2*i] = (long)endTime[i] * 2;
            ev[2*i+1] = (long)startTime[i] * 2 + 1;
        }
        java.util.Arrays.sort(ev);
        int cur = 0, best = 0;
        for (long e : ev) {
            cur += (e & 1) == 1 ? 1 : -1;
            best = Math.max(best, cur);
        }
        return Math.max(best, 1);
    }
}

